import React, { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { ArrowDown, History, LoaderCircle, MessageSquare } from 'lucide-react';

const getCaptionId = (caption) => caption.captionId || caption.utteranceId;

const CaptionPanel = ({
    captions,
    participantNames = {},
    hasOlderCaptions = false,
    loadingHistory = false,
    historyError,
    onLoadOlder
}) => {
    const scrollRef = useRef(null);
    const nearBottomRef = useRef(true);
    const restoreScrollRef = useRef(null);
    const initializedRef = useRef(false);
    const [showNewCaptions, setShowNewCaptions] = useState(false);

    const getSpeakerName = (caption) => caption.speakerName || participantNames[caption.speakerId] || caption.speakerId || 'Unknown';

    const formatTime = (caption) => {
        if (caption.createdAt) {
            return new Date(caption.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
        }
        if (!caption.start && caption.start !== 0) return '';
        return new Date(caption.start * 1000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    };

    const scrollToBottom = (behavior = 'smooth') => {
        const container = scrollRef.current;
        if (!container) return;
        container.scrollTo({ top: container.scrollHeight, behavior });
        nearBottomRef.current = true;
        setShowNewCaptions(false);
    };

    const handleScroll = () => {
        const container = scrollRef.current;
        if (!container) return;
        nearBottomRef.current = container.scrollHeight - container.scrollTop - container.clientHeight < 80;
        if (nearBottomRef.current) setShowNewCaptions(false);
    };

    const handleLoadOlder = async () => {
        const container = scrollRef.current;
        if (!container || !onLoadOlder || loadingHistory) return;
        restoreScrollRef.current = {
            firstCaptionId: getCaptionId(captions[0]),
            lastCaptionId: getCaptionId(captions[captions.length - 1]),
            scrollHeight: container.scrollHeight,
            scrollTop: container.scrollTop
        };
        const loaded = await onLoadOlder();
        if (!loaded) restoreScrollRef.current = null;
    };

    useLayoutEffect(() => {
        const container = scrollRef.current;
        if (!container || captions.length === 0) {
            initializedRef.current = false;
            return;
        }

        const restore = restoreScrollRef.current;
        if (restore && getCaptionId(captions[0]) !== restore.firstCaptionId) {
            const liveCaptionArrived = getCaptionId(captions[captions.length - 1]) !== restore.lastCaptionId;
            container.scrollTop = restore.scrollTop + container.scrollHeight - restore.scrollHeight;
            restoreScrollRef.current = null;
            if (liveCaptionArrived) {
                const frame = window.requestAnimationFrame(() => setShowNewCaptions(true));
                return () => window.cancelAnimationFrame(frame);
            }
            return;
        }
        if (restore) {
            if (getCaptionId(captions[captions.length - 1]) !== restore.lastCaptionId) {
                restore.lastCaptionId = getCaptionId(captions[captions.length - 1]);
                const frame = window.requestAnimationFrame(() => setShowNewCaptions(true));
                return () => window.cancelAnimationFrame(frame);
            }
            return;
        }

        if (!initializedRef.current) {
            initializedRef.current = true;
            container.scrollTop = container.scrollHeight;
            nearBottomRef.current = true;
            return;
        }

        if (nearBottomRef.current) {
            container.scrollTo({ top: container.scrollHeight, behavior: 'smooth' });
        } else {
            const frame = window.requestAnimationFrame(() => setShowNewCaptions(true));
            return () => window.cancelAnimationFrame(frame);
        }
    }, [captions]);

    useEffect(() => {
        if (!hasOlderCaptions && !loadingHistory) restoreScrollRef.current = null;
    }, [hasOlderCaptions, loadingHistory]);

    return (
        <div className="flex h-full min-h-0 flex-col overflow-hidden">
            <div className="mb-3 shrink-0 rounded-2xl border border-white/10 bg-white/[0.04] px-3.5 py-3">
                <div className="flex items-center justify-between gap-3">
                    <div className="flex items-center gap-2 text-sm font-bold text-slate-200">
                        <MessageSquare size={15} className="text-blue-300" />
                        <span>Transcript</span>
                    </div>
                    <span className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-600">
                        {captions.length} loaded
                    </span>
                </div>
            </div>

            <div ref={scrollRef} onScroll={handleScroll} className="relative min-h-0 flex-1 overflow-y-auto pr-1">
                {hasOlderCaptions && (
                    <button
                        type="button"
                        onClick={handleLoadOlder}
                        disabled={loadingHistory}
                        className="mb-3 flex w-full items-center justify-center gap-2 rounded-xl border border-white/10 bg-white/[0.04] px-3 py-2.5 text-[10px] font-black uppercase tracking-[0.14em] text-slate-400 transition hover:bg-white/[0.08] hover:text-slate-200 disabled:cursor-wait disabled:opacity-50"
                    >
                        {loadingHistory ? <LoaderCircle size={14} className="animate-spin" /> : <History size={14} />}
                        {loadingHistory ? 'Loading history...' : 'Load older captions'}
                    </button>
                )}

                {historyError && (
                    <div className="mb-3 rounded-xl border border-red-400/15 bg-red-400/[0.07] px-3 py-2 text-xs leading-5 text-red-200/80">
                        {historyError}
                    </div>
                )}

                {captions.length === 0 ? (
                    <div className="flex h-full min-h-48 flex-col items-center justify-center rounded-2xl border border-dashed border-white/10 p-6 text-center text-slate-500">
                        {loadingHistory ? <LoaderCircle size={24} className="animate-spin" /> : <MessageSquare size={24} />}
                        <p className="mt-3 text-sm font-bold text-slate-300">{loadingHistory ? 'Loading transcript' : 'Waiting for speech'}</p>
                        <p className="mt-1 text-xs leading-5">{loadingHistory ? 'Retrieving this session’s captions.' : 'Live captions will appear here.'}</p>
                    </div>
                ) : (
                    <div className="space-y-2.5 pb-1">
                        {captions.map((caption, index) => (
                            <article key={getCaptionId(caption) || `caption-${index}`} className="rounded-2xl border border-white/10 bg-white/[0.04] p-3 transition hover:bg-white/[0.07]">
                                <div className="mb-1.5 flex items-center justify-between gap-3">
                                    <span className="truncate text-[10px] font-black uppercase tracking-[0.16em] text-blue-300">
                                        {getSpeakerName(caption)}
                                    </span>
                                    <time className="shrink-0 text-[10px] font-semibold text-slate-600">{formatTime(caption)}</time>
                                </div>
                                <p className="break-words text-xs font-medium leading-5 text-slate-300">{caption.text}</p>
                            </article>
                        ))}
                    </div>
                )}
            </div>

            {showNewCaptions && (
                <button
                    type="button"
                    onClick={() => scrollToBottom()}
                    className="mt-2 flex shrink-0 items-center justify-center gap-2 rounded-xl border border-blue-400/20 bg-blue-400/10 px-3 py-2 text-[10px] font-black uppercase tracking-[0.14em] text-blue-200 transition hover:bg-blue-400/20"
                >
                    <ArrowDown size={14} /> New captions
                </button>
            )}
        </div>
    );
};

export default CaptionPanel;

import React, { useEffect, useState } from 'react';
import ReactMarkdown from 'react-markdown';
import { ArrowLeft, Check, CheckCircle2, ChevronDown, CircleHelp, ClipboardCopy, FileText, RefreshCw, Settings, Share2, Sparkles } from 'lucide-react';
import { getActiveApiKey, getProviderConfig, getSelectedModel } from '../config/llmModels';

const buildSummaryText = (summary) => {
    const sections = [];
    const executive = typeof summary?.executive === 'string' ? summary.executive.trim() : '';
    const detailed = typeof summary?.raw === 'string' ? summary.raw.trim() : '';
    const actions = Array.isArray(summary?.actions) ? summary.actions.filter(Boolean) : [];
    const questions = typeof summary?.questions === 'string' ? summary.questions.trim() : '';

    if (executive) sections.push(`Overview\n${executive}`);
    if (detailed) sections.push(`Detailed summary\n${detailed}`);
    if (actions.length) sections.push(`Actions\n${actions.map((item) => `- ${item}`).join('\n')}`);
    if (questions) sections.push(`Open questions\n${questions}`);

    return sections.join('\n\n');
};

const markdownComponents = {
    h1: ({ children }) => <h1 className="mb-3 mt-6 text-xl font-black tracking-tight text-white first:mt-0">{children}</h1>,
    h2: ({ children }) => <h2 className="mb-2.5 mt-5 text-base font-black tracking-tight text-slate-100 first:mt-0">{children}</h2>,
    h3: ({ children }) => <h3 className="mb-2 mt-4 text-sm font-bold text-blue-200 first:mt-0">{children}</h3>,
    p: ({ children }) => <p className="my-3 text-sm leading-6 text-slate-300 first:mt-0 last:mb-0">{children}</p>,
    ul: ({ children }) => <ul className="my-3 list-disc space-y-2 pl-5 text-sm leading-6 text-slate-300 marker:text-blue-400">{children}</ul>,
    ol: ({ children }) => <ol className="my-3 list-decimal space-y-2 pl-5 text-sm leading-6 text-slate-300 marker:font-bold marker:text-blue-300">{children}</ol>,
    li: ({ children }) => <li className="pl-1">{children}</li>,
    strong: ({ children }) => <strong className="font-bold text-slate-100">{children}</strong>,
    blockquote: ({ children }) => <blockquote className="my-4 border-l-2 border-blue-400/50 bg-blue-400/[0.06] py-1 pl-3 italic text-slate-300">{children}</blockquote>,
    a: ({ children, href }) => <a href={href} target="_blank" rel="noreferrer" className="text-blue-300 underline decoration-blue-400/40 underline-offset-2 hover:text-blue-200">{children}</a>,
    code: ({ children }) => <code className="break-words rounded bg-black/30 px-1.5 py-0.5 font-mono text-[0.85em] text-blue-100">{children}</code>,
    pre: ({ children }) => <pre className="my-4 overflow-x-auto rounded-xl border border-white/10 bg-black/30 p-3 text-xs leading-5">{children}</pre>,
    hr: () => <hr className="my-5 border-white/10" />
};

const SummaryPanel = ({ summary, onGenerate, generating, llmConfig, onOpenSettings }) => {
    const hasApiKey = getActiveApiKey(llmConfig).trim().length > 0;
    const selectedModel = getSelectedModel(llmConfig);
    const generatedProvider = getProviderConfig(summary?._meta?.provider || llmConfig?.provider);
    const generatedModel = generatedProvider.models.find((model) => model.id === summary?._meta?.model) || selectedModel;
    const [timeRange, setTimeRange] = useState('full');
    const [actionsOpen, setActionsOpen] = useState(false);
    const [questionsOpen, setQuestionsOpen] = useState(false);
    const [actionFeedback, setActionFeedback] = useState(null);
    const [isConfiguringSummary, setIsConfiguringSummary] = useState(false);

    useEffect(() => {
        if (!actionFeedback) return undefined;
        const timeout = window.setTimeout(() => setActionFeedback(null), 2000);
        return () => window.clearTimeout(timeout);
    }, [actionFeedback]);

    const handleGenerate = async () => {
        const minutes = timeRange === 'full' ? null : parseInt(timeRange, 10);
        const generated = await onGenerate(minutes);

        if (generated) {
            setIsConfiguringSummary(false);
            setActionsOpen(false);
            setQuestionsOpen(false);
            setActionFeedback(null);
        }
    };

    const handleStartAnotherSummary = () => {
        setTimeRange('full');
        setActionFeedback(null);
        setIsConfiguringSummary(true);
    };

    const handleCopy = async () => {
        try {
            await navigator.clipboard.writeText(buildSummaryText(summary));
            setActionFeedback('copied');
        } catch (error) {
            console.error('Failed to copy summary:', error);
            setActionFeedback('error');
        }
    };

    const handleShare = async () => {
        const text = buildSummaryText(summary);

        if (!navigator.share) {
            await handleCopy();
            return;
        }

        try {
            await navigator.share({ title: 'Meeting summary', text });
            setActionFeedback('shared');
        } catch (error) {
            if (error.name !== 'AbortError') {
                console.error('Failed to share summary:', error);
                setActionFeedback('error');
            }
        }
    };

    const timeRangeOptions = [
        { value: 'full', label: 'Full' },
        { value: '15', label: '15m' },
        { value: '30', label: '30m' },
        { value: '60', label: '1h' }
    ];

    return (
        <div className="flex h-full min-h-0 flex-col overflow-hidden">
            {!summary || isConfiguringSummary ? (
                <div className="flex h-full min-h-0 flex-col gap-3">
                    {summary && (
                        <button
                            type="button"
                            onClick={() => setIsConfiguringSummary(false)}
                            disabled={generating}
                            className="flex w-fit items-center gap-2 rounded-xl border border-white/10 bg-white/[0.04] px-3 py-2 text-[10px] font-black uppercase tracking-[0.14em] text-slate-300 transition hover:bg-white/[0.08] hover:text-white focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-400 disabled:cursor-wait disabled:opacity-50"
                        >
                            <ArrowLeft size={13} /> Back to summary
                        </button>
                    )}
                    <div className="rounded-2xl border border-blue-400/20 bg-blue-400/10 p-4">
                        <div className="mb-2 flex items-center gap-2 text-blue-200">
                            <Sparkles size={17} />
                            <h3 className="text-sm font-black uppercase tracking-[0.16em]">AI Summary</h3>
                        </div>
                        <p className="text-sm leading-5 text-blue-100/70">
                            Convert this meeting into summary, actions, and questions.
                        </p>
                    </div>

                    <div className="flex flex-wrap gap-2">
                        {['Summary', 'Actions', 'Questions'].map((item) => (
                            <span key={item} className="rounded-full border border-white/10 bg-white/[0.05] px-3 py-1.5 text-[10px] font-black uppercase tracking-[0.14em] text-slate-400">
                                {item}
                            </span>
                        ))}
                    </div>

                    {/* Time range selector */}
                    <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-3">
                        <p className="text-[10px] font-black uppercase tracking-[0.14em] text-gray-500 mb-2">Summarize</p>
                        <div className="grid grid-cols-4 gap-1.5">
                            {timeRangeOptions.map((opt) => (
                                <button
                                    key={opt.value}
                                    onClick={() => setTimeRange(opt.value)}
                                    disabled={generating}
                                    className={`rounded-xl py-2 text-[10px] font-black uppercase tracking-[0.12em] transition-all ${
                                        timeRange === opt.value
                                            ? 'bg-blue-500/20 border border-blue-400/30 text-blue-200'
                                            : 'bg-white/[0.04] border border-white/10 text-gray-500 hover:text-gray-300 hover:bg-white/[0.08]'
                                    } disabled:cursor-wait disabled:opacity-50`}
                                >
                                    {opt.label}
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="mt-auto">
