/* Base Styles */"},{"oldText":":root {
  --background: #0f0f0f;
  --foreground: #ffffff;
  --border: rgba(255, 255, 255, 0.05);
}","newText":":root {
  --background: #0f0f0f;
  --foreground: #ffffff;
  --border: rgba(255, 255, 255, 0.05);
  --surface: #171717;
  --surface-elevated: #262626;
  --muted-foreground: #94a3b8;
  --theme-transition-duration: 180ms;
}

:root[data-theme='light'] {
  --background: #f8fafc;
  --foreground: #0f172a;
  --border: #cbd5e1;
  --surface: #ffffff;
  --surface-elevated: #f1f5f9;
  --muted-foreground: #475569;
  --theme-transition-duration: 180ms;
  color-scheme: light;
}

.theme-shell {
  background-color: var(--background);
  color: var(--foreground);
}

[data-theme='light'] .join-shell,
[data-theme='light'] .meeting-shell {
  background-image: linear-gradient(rgba(248, 250, 252, 0.94), rgba(248, 250, 252, 0.94));
}

.theme-transition,
.theme-transition * {
  transition-property: color, background-color, border-color, box-shadow, fill, stroke !important;
  transition-duration: var(--theme-transition-duration) !important;
  transition-timing-function: ease-out !important;
