export const DEFAULT_THEME = 'dark';
export const THEME_STORAGE_KEY = 'meetsummarizer_theme';
export const THEME_VALUES = Object.freeze(['dark', 'light']);

export const isValidTheme = (value) => THEME_VALUES.includes(value);

export const normalizeTheme = (value) => (isValidTheme(value) ? value : DEFAULT_THEME);

const getStorage = (storage) => storage ?? globalThis.localStorage;

export const getThemePreference = (storage) => {
  try {
    return normalizeTheme(getStorage(storage)?.getItem(THEME_STORAGE_KEY));
  } catch {
    return DEFAULT_THEME;
  }
};

export const setThemePreference = (theme, storage) => {
  const normalizedTheme = normalizeTheme(theme);

  try {
    getStorage(storage)?.setItem(THEME_STORAGE_KEY, normalizedTheme);
  } catch {
    // Renderer storage can be unavailable or disabled; the in-memory state still applies.
  }

  return normalizedTheme;
};

// Descriptive aliases keep the read/write behavior easy to discover at call sites.
export const readThemePreference = getThemePreference;
export const writeThemePreference = setThemePreference;
export const getStoredTheme = getThemePreference;
export const setStoredTheme = setThemePreference;

import assert from 'node:assert/strict';
import test from 'node:test';
import {
  DEFAULT_THEME,
  THEME_STORAGE_KEY,
  getThemePreference,
  isValidTheme,
  setThemePreference
} from '../src/utils/themePreference.js';

const createStorage = (initial = {}) => {
  const values = new Map(Object.entries(initial));
  return {
    getItem(key) {
      return values.has(key) ? values.get(key) : null;
    },
    setItem(key, value) {
      values.set(key, String(value));
    },
    value(key) {
      return values.get(key);
    }
  };
};

test('theme preference defaults to dark when no value is stored', () => {
  assert.equal(getThemePreference(createStorage()), DEFAULT_THEME);
});

test('invalid stored values fall back to dark without changing the raw entry', () => {
  const storage = createStorage({ [THEME_STORAGE_KEY]: 'system' });

  assert.equal(getThemePreference(storage), DEFAULT_THEME);
  assert.equal(storage.value(THEME_STORAGE_KEY), 'system');
});

test('valid stored values are returned unchanged', () => {
  const storage = createStorage({ [THEME_STORAGE_KEY]: 'light' });

  assert.equal(getThemePreference(storage), 'light');
  assert.equal(isValidTheme('dark'), true);
  assert.equal(isValidTheme('light'), true);
  assert.equal(isValidTheme('system'), false);
});

test('writing a theme uses a direct non-expiring storage value', () => {
  const storage = createStorage();

  assert.equal(setThemePreference('light', storage), 'light');
  assert.equal(storage.value(THEME_STORAGE_KEY), 'light');
  assert.equal(getThemePreference(storage), 'light');

  assert.equal(setThemePreference('invalid', storage), DEFAULT_THEME);
  assert.equal(storage.value(THEME_STORAGE_KEY), DEFAULT_THEME);
});

import React from 'react';
import { Moon, Sun } from 'lucide-react';

const ThemeToggle = ({ theme = 'dark', onThemeChange, className = '' }) => {
    const nextTheme = theme === 'light' ? 'dark' : 'light';
    const label = `Switch to ${nextTheme} theme`;
    const Icon = theme === 'light' ? Moon : Sun;

    return (
        <button
            type="button"
            onClick={() => onThemeChange?.(nextTheme)}
            aria-label={label}
            aria-pressed={theme === 'light'}
            title={label}
            className={`flex size-10 items-center justify-center rounded-xl border border-white/10 bg-white/[0.06] text-slate-200 shadow-sm transition-colors hover:bg-white/[0.12] hover:text-white focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-400 light:border-slate-300 light:bg-white light:text-slate-700 light:hover:bg-slate-100 light:hover:text-slate-950 ${className}`}
        >
            <Icon size={18} aria-hidden="true" />
            <span className="sr-only">{label}</span>
        </button>
    );
};

export default React.memo(ThemeToggle);

